class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        pre_sets = [set(arr) for arr in properties]
        adj = [[] for _ in range(n)]

        for i in range(n):
            for j in range(n):
                if i != j:
                    common = len(pre_sets[i] & pre_sets[j])
                    if common >= k:
                        adj[i].append(j)

        visited = [False] * n
        count = 0

        for i in range(n):
            if not visited[i]:
                count += 1
                queue = deque()
                queue.append(i)
                visited[i] = True
                while queue:
                    node = queue.popleft()
                    for neighbor in adj[node]:
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            queue.append(neighbor)

        return count
