class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        parent = list(range(n))

        def find(x: int) -> int:
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x: int, y: int) -> None:
            root_x = find(x)
            root_y = find(y)
            if root_x != root_y:
                parent[root_x] = root_y

        for i in range(n):
            for j in range(i + 1, n):
                set_i = set(properties[i])
                set_j = set(properties[j])
                common = set_i & set_j
                if len(common) >= k:
                    union(i, j)

        roots = set()
        for i in range(n):
            roots.add(find(i))

        return len(roots)
